initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector('#log-tbody');
  let allLogs = [];
  let autoRefreshInterval = null;

  // ステータス表示用のヘルパー関数
  function getStatusBadge(status) {
    const statusMap = {
      '成功': { color: '#22c55e', bg: 'rgba(34, 197, 94, 0.1)' },
      '失敗': { color: '#ef4444', bg: 'rgba(239, 68, 68, 0.1)' },
      '実行中': { color: '#f59e0b', bg: 'rgba(245, 158, 11, 0.1)' },
      '警告': { color: '#f59e0b', bg: 'rgba(245, 158, 11, 0.1)' }
    };
    const style = statusMap[status] || { color: 'var(--text-muted)', bg: 'var(--bg-card)' };
    return `<span style="background: ${style.bg}; color: ${style.color}; padding: 4px 8px; border-radius: 4px; font-size: 12px; font-weight: 500;">${status}</span>`;
  }

  // ログレベル判定
  function getLogLevel(status, errorCount) {
    if (status === '失敗' || errorCount > 0) return 'ERROR';
    if (status === '警告') return 'WARN';
    return 'INFO';
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP');
  }

  // 店舗名取得
  function getStoreName(storeId) {
    if (!storeId || !tables[1]) return '-';
    const store = tables[1].records?.find(s => s.店舗ID === storeId);
    return store ? store.店舗名 : '-';
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.ログID}">
        <td>${formatDateTime(r.収集開始日時)}</td>
        <td>${r.データ種別 || '-'}</td>
        <td>${r.データソース || '-'}</td>
        <td>${getStoreName(r.店舗ID)}</td>
        <td>${getStatusBadge(r.処理ステータス)}</td>
        <td style="text-align: right;">${(r.収集件数 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(r.エラー件数 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${r.処理時間秒 || 0}秒</td>
        <td style="text-align: right;">${r.データ品質スコア || '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.ログID}">詳細</button>
          ${r.処理ステータス === '失敗' ? `<button class="action-btn secondary retry-btn" data-id="${r.ログID}">再実行</button>` : ''}
        </td>
      </tr>
    `).join('');

    updateSummary(rows);
    updateErrorIndicator(rows);
  }

  // サマリー更新
  function updateSummary(rows) {
    const totalCount = rows.reduce((sum, r) => sum + (r.収集件数 || 0), 0);
    const successCount = rows.filter(r => r.処理ステータス === '成功').reduce((sum, r) => sum + (r.収集件数 || 0), 0);
    const errorCount = rows.reduce((sum, r) => sum + (r.エラー件数 || 0), 0);
    const lastExecution = rows.length > 0 ? formatDateTime(rows[0].収集開始日時) : '-';

    container.querySelector('#total-count').textContent = totalCount.toLocaleString();
    container.querySelector('#success-count').textContent = successCount.toLocaleString();
    container.querySelector('#error-count').textContent = errorCount.toLocaleString();
    container.querySelector('#last-execution').textContent = lastExecution;
  }

  // エラーインジケーター更新
  function updateErrorIndicator(rows) {
    const hasErrors = rows.some(r => r.処理ステータス === '失敗' || (r.エラー件数 || 0) > 0);
    const indicator = container.querySelector('#error-indicator');
    if (hasErrors) {
      indicator.classList.remove('hidden');
    } else {
      indicator.classList.add('hidden');
    }
  }

  // フィルタリング関数
  function applyFilters() {
    const datasource = container.querySelector('#filter-datasource').value;
    const loglevel = container.querySelector('#filter-loglevel').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    // 日付範囲バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を設定してください');
      return;
    }

    let filtered = allLogs.filter(log => {
      // データソースフィルター
      if (datasource && log.データソース !== datasource) return false;

      // ログレベルフィルター
      if (loglevel) {
        const logLevel = getLogLevel(log.処理ステータス, log.エラー件数);
        if (logLevel !== loglevel) return false;
      }

      // 日付範囲フィルター
      if (startDate && log.収集開始日時 && new Date(log.収集開始日時) < new Date(startDate)) return false;
      if (endDate && log.収集開始日時 && new Date(log.収集開始日時) > new Date(endDate)) return false;

      return true;
    });

    renderRows(filtered);
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['収集日時', 'データ種別', 'データソース', '店舗名', 'ステータス', '収集件数', 'エラー件数', '処理時間', '品質スコア'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allLogs.map(log => [
        formatDateTime(log.収集開始日時),
        log.データ種別 || '',
        log.データソース || '',
        getStoreName(log.店舗ID),
        log.処理ステータス || '',
        log.収集件数 || 0,
        log.エラー件数 || 0,
        (log.処理時間秒 || 0) + '秒',
        log.データ品質スコア || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // ログ詳細表示
  function showLogDetail(logId) {
    const log = allLogs.find(l => l.ログID === logId);
    if (!log) return;

    const modalBody = container.querySelector('#modal-content-body');
    modalBody.innerHTML = `
      <div style="display: grid; gap: 16px;">
        <div style="display: grid; grid-template-columns: 150px 1fr; gap: 8px; align-items: center;">
          <strong>ログID:</strong><span>${log.ログID}</span>
          <strong>データ種別:</strong><span>${log.データ種別 || '-'}</span>
          <strong>データソース:</strong><span>${log.データソース || '-'}</span>
          <strong>店舗:</strong><span>${getStoreName(log.店舗ID)}</span>
          <strong>収集開始日時:</strong><span>${formatDateTime(log.収集開始日時)}</span>
          <strong>収集終了日時:</strong><span>${formatDateTime(log.収集終了日時)}</span>
          <strong>処理ステータス:</strong><span>${getStatusBadge(log.処理ステータス)}</span>
          <strong>対象期間:</strong><span>${formatDateTime(log.対象期間開始日)} ～ ${formatDateTime(log.対象期間終了日)}</span>
          <strong>収集件数:</strong><span>${(log.収集件数 || 0).toLocaleString()}件</span>
          <strong>エラー件数:</strong><span>${(log.エラー件数 || 0).toLocaleString()}件</span>
          <strong>処理時間:</strong><span>${log.処理時間秒 || 0}秒</span>
          <strong>データ品質スコア:</strong><span>${log.データ品質スコア || '-'}</span>
        </div>
        ${log.エラーメッセージ ? `
          <div>
            <strong style="color: var(--text);">エラーメッセージ:</strong>
            <div style="background: var(--bg-main); border: 1px solid var(--border); border-radius: 4px; padding: 12px; margin-top: 8px; font-family: monospace; white-space: pre-wrap; max-height: 200px; overflow-y: auto;">${log.エラーメッセージ}</div>
          </div>
        ` : ''}
        ${log.備考 ? `
          <div>
            <strong style="color: var(--text);">備考:</strong>
            <div style="margin-top: 8px;">${log.備考}</div>
          </div>
        ` : ''}
      </div>
    `;

    container.querySelector('#log-detail-modal').classList.remove('hidden');
  }

  // エラーログ再実行
  async function retryErrorLog(logId) {
    if (!confirm('このログの処理を再実行しますか？')) return;

    try {
      // 再実行処理をシミュレート
      const log = allLogs.find(l => l.ログID === logId);
      if (log) {
        const updated = await window.aivicApi.update(12, logId, {
          処理ステータス: '成功',
          エラー件数: 0,
          エラーメッセージ: null,
          再実行フラグ: false,
          更新日時: new Date().toISOString()
        });

        if (updated) {
          alert('再実行が完了しました');
          loadLogs();
        } else {
          alert('再実行に失敗しました');
        }
      }
    } catch (error) {
      alert('再実行に失敗しました: ' + error.message);
    }
  }

  // 自動更新設定
  function toggleAutoRefresh() {
    const isEnabled = container.querySelector('#auto-refresh-toggle').checked;

    if (isEnabled) {
      autoRefreshInterval = setInterval(() => {
        loadLogs();
      }, 30000); // 30秒間隔
    } else {
      if (autoRefreshInterval) {
        clearInterval(autoRefreshInterval);
        autoRefreshInterval = null;
      }
    }
  }

  // ログデータ読み込み
  async function loadLogs() {
    try {
      const logs = await window.aivicApi.list(12);
      if (logs) {
        allLogs = logs.sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時));
        renderRows(allLogs);
      }
    } catch (error) {
      console.error('ログ読み込みエラー:', error);
    }
  }

  // 初期データ表示
  allLogs = (tables[12]?.records || []).sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時));
  renderRows(allLogs);

  // 最新データ読み込み
  loadLogs();

  // イベントリスナー登録
  container.querySelector('#btn-search').addEventListener('click', applyFilters);
  container.querySelector('#btn-export').addEventListener('click', exportCSV);
  container.querySelector('#auto-refresh-toggle').addEventListener('change', toggleAutoRefresh);

  // モーダル関連
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#log-detail-modal').classList.add('hidden');
  });

  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.remove('hidden');
  });

  container.querySelector('#btn-close-alert-modal').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.add('hidden');
  });

  container.querySelector('#btn-error-details').addEventListener('click', () => {
    const errorLogs = allLogs.filter(log => log.処理ステータス === '失敗' || (log.エラー件数 || 0) > 0);
    if (errorLogs.length > 0) {
      showLogDetail(errorLogs[0].ログID);
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const retryBtn = e.target.closest('.retry-btn');

    if (detailBtn) {
      showLogDetail(detailBtn.dataset.id);
    }

    if (retryBtn) {
      await retryErrorLog(retryBtn.dataset.id);
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#log-detail-modal').addEventListener('click', (e) => {
    if (e.target.classList.contains('modal')) {
      container.querySelector('#log-detail-modal').classList.add('hidden');
    }
  });

  container.querySelector('#alert-settings-modal').addEventListener('click', (e) => {
    if (e.target.classList.contains('modal')) {
      container.querySelector('#alert-settings-modal').classList.add('hidden');
    }
  });
}
